CREATE TABLE IF NOT EXISTS "contests" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "start_date_time" TEXT NOT NULL, "end_date_time" TEXT NOT NULL, "timezone" TEXT NOT NULL, "host" TEXT NULL, "city" TEXT NULL, "state" TEXT NULL, "country" TEXT NULL, "owner_account_id" TEXT NULL, "lifecycle_state" TEXT NOT NULL CHECK("lifecycle_state" IN ('Created', 'Configuring', 'Ready', 'Running', 'Completed')), "scoring_access" TEXT NOT NULL CHECK("scoring_access" IN ('Closed', 'Open')), "admin_lock" TEXT NOT NULL CHECK("admin_lock" IN ('Unlocked', 'Locked')), "results_hidden_through_round" INTEGER NULL, "results_hidden_at" TEXT NULL, "local_archive" INTEGER NOT NULL DEFAULT 0 CHECK ("local_archive" IN (0, 1)), "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "landing_tables" ("id" TEXT NOT NULL, "owner_account_id" TEXT NULL, "name" TEXT NOT NULL, "input_unit" TEXT NOT NULL CHECK("input_unit" IN ('meters', 'feet', 'points')), "created_at" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "landing_results" ("id" TEXT NOT NULL, "landing_table_id" TEXT NOT NULL REFERENCES landing_tables (id), "entry_key" TEXT NOT NULL, "display_value" TEXT NOT NULL, "point_value" INTEGER NOT NULL, "ordinal_position" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("landing_table_id", "entry_key"), UNIQUE ("landing_table_id", "ordinal_position"));
CREATE TABLE IF NOT EXISTS "discipline_profiles" ("id" TEXT NOT NULL, "type" TEXT NOT NULL CHECK("type" IN ('ALES', 'ThermalDuration', 'F3J', 'F5J', 'F3L', 'F3K')), "version" INTEGER NOT NULL, "name" TEXT NOT NULL, "description" TEXT NULL, "category" TEXT NOT NULL CHECK("category" IN ('duration', 'multiple', 'other')), "default_landing_table_id" TEXT NULL REFERENCES landing_tables (id), "default_options" TEXT NULL, "status" TEXT NOT NULL CHECK("status" IN ('drafted', 'published', 'superseded')), "superseded_by" TEXT NULL REFERENCES discipline_profiles (id), "created_by" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_by" TEXT NULL, "updated_at" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("type", "version"));
CREATE TABLE IF NOT EXISTS "discipline_config_fields" ("id" TEXT NOT NULL, "discipline_profile_id" TEXT NOT NULL REFERENCES discipline_profiles (id), "field_key" TEXT NOT NULL, "field_type" TEXT NOT NULL CHECK("field_type" IN ('string', 'int', 'float', 'bool', 'enum', 'landing')), "name" TEXT NOT NULL, "description" TEXT NULL, "unit" TEXT NULL, "required" INTEGER NOT NULL CHECK ("required" IN (0, 1)), "default_value" TEXT NULL, "options" TEXT NULL, "validation" TEXT NULL, "display_order" INTEGER NOT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("discipline_profile_id", "field_key"));
CREATE TABLE IF NOT EXISTS "discipline_score_fields" ("id" TEXT NOT NULL, "discipline_profile_id" TEXT NOT NULL REFERENCES discipline_profiles (id), "field_key" TEXT NOT NULL, "field_type" TEXT NOT NULL CHECK("field_type" IN ('string', 'int', 'float', 'bool', 'enum', 'date', 'time', 'landing')), "name" TEXT NOT NULL, "description" TEXT NULL, "field_kind" TEXT NOT NULL CHECK("field_kind" IN ('input', 'status_flag', 'derived')), "unit" TEXT NULL, "precision" INTEGER NULL, "required" INTEGER NOT NULL CHECK ("required" IN (0, 1)), "default_value" TEXT NULL, "options" TEXT NULL, "validation" TEXT NULL, "display_order" INTEGER NOT NULL, "is_zero_reason" INTEGER NOT NULL CHECK ("is_zero_reason" IN (0, 1)), "zero_reason_code" TEXT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("discipline_profile_id", "field_key"));
CREATE TABLE IF NOT EXISTS "discipline_validations" ("id" TEXT NOT NULL, "discipline_profile_id" TEXT NOT NULL REFERENCES discipline_profiles (id), "field_keys" TEXT NOT NULL, "constraint_type" TEXT NOT NULL, "description" TEXT NULL, "applies_to" TEXT NULL, "message" TEXT NULL, "display_order" INTEGER NOT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("discipline_profile_id", "field_keys", "constraint_type"));
CREATE TABLE IF NOT EXISTS "discipline_formulas" ("id" TEXT NOT NULL, "discipline_profile_id" TEXT NOT NULL REFERENCES discipline_profiles (id), "formula_key" TEXT NOT NULL, "description" TEXT NULL, "formula_text" TEXT NOT NULL, "formula_type" TEXT NOT NULL CHECK("formula_type" IN ('raw', 'intermediate', 'penalty', 'final', 'normalized')), "inputs" TEXT NOT NULL, "outputs" TEXT NULL, "depends_on" TEXT NOT NULL, "is_primary" INTEGER NOT NULL CHECK ("is_primary" IN (0, 1)), "display_order" INTEGER NOT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("discipline_profile_id", "formula_key"));
CREATE TABLE IF NOT EXISTS "discipline_rules" ("id" TEXT NOT NULL, "discipline_profile_id" TEXT NOT NULL REFERENCES discipline_profiles (id), "rule_key" TEXT NOT NULL, "rule_type" TEXT NOT NULL CHECK("rule_type" IN ('calc', 'penalty', 'zero', 'interaction', 'other')), "condition" TEXT NULL, "effect" TEXT NULL, "applies_to" TEXT NULL, "depends_on" TEXT NOT NULL, "display_name" TEXT NULL, "description" TEXT NULL, "auto_score_zero" INTEGER NOT NULL CHECK ("auto_score_zero" IN (0, 1)), "affects_other_fields" TEXT NOT NULL, "display_order" INTEGER NOT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("discipline_profile_id", "rule_key"));
CREATE TABLE IF NOT EXISTS "contest_configuration_presets" ("id" TEXT NOT NULL, "owner_account_id" TEXT NOT NULL, "discipline_profile_id" TEXT NOT NULL REFERENCES discipline_profiles (id), "name" TEXT NOT NULL, "description" TEXT NULL, "config" TEXT NOT NULL, "landing_table_id" TEXT NULL REFERENCES landing_tables (id), "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "contest_configuration_revisions" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "revision_number" INTEGER NOT NULL, "discipline_profile_id" TEXT NOT NULL REFERENCES discipline_profiles (id), "source_preset_id" TEXT NULL REFERENCES contest_configuration_presets (id) ON DELETE SET NULL, "config" TEXT NOT NULL, "landing_table_id" TEXT NULL REFERENCES landing_tables (id), "created_by" TEXT NOT NULL, "notes" TEXT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("contest_id", "revision_number"));
CREATE TABLE IF NOT EXISTS "participant_profiles" ("id" TEXT NOT NULL, "owner_account_id" TEXT NOT NULL, "first_name" TEXT NOT NULL, "last_name" TEXT NOT NULL, "club" TEXT NULL, "fai_number" TEXT NULL, "national_org_id" TEXT NULL, "city" TEXT NULL, "state" TEXT NULL, "country" TEXT NULL, "email" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "roles" ("id" TEXT NOT NULL, "owner_account_id" TEXT NULL, "display_name" TEXT NOT NULL, "type" TEXT NOT NULL CHECK("type" IN ('Pilot', 'NonFlier')), "archived_at" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "contest_participations" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "participant_profile_id" TEXT NOT NULL REFERENCES participant_profiles (id), "classification" TEXT NULL, "role_id" TEXT NOT NULL REFERENCES roles (id), "role_name" TEXT NOT NULL, "role_type" TEXT NOT NULL CHECK("role_type" IN ('Pilot', 'NonFlier')), "participant_number" INTEGER NULL, "scoring_uuid" TEXT NOT NULL, "retired_at_round" INTEGER NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("contest_id", "participant_number"), UNIQUE ("contest_id", "scoring_uuid"), UNIQUE ("contest_id", "participant_profile_id"));
CREATE TABLE IF NOT EXISTS "teams" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("contest_id", "name"));
CREATE TABLE IF NOT EXISTS "team_memberships" ("id" TEXT NOT NULL, "team_id" TEXT NOT NULL REFERENCES teams (id), "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("team_id", "contest_participation_id"));
CREATE TABLE IF NOT EXISTS "model_catalogs" ("id" TEXT NOT NULL, "owner_account_id" TEXT NOT NULL, "participant_profile_id" TEXT NOT NULL, "name" TEXT NOT NULL, "manufacturer" TEXT NULL, "model_id" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "contest_model_links" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "model_catalog_id" TEXT NULL REFERENCES model_catalogs (id) ON DELETE SET NULL, "model_name" TEXT NOT NULL, "manufacturer" TEXT NULL, "model_id" TEXT NULL, "contest_specific_identifier" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "import_provenance" ("id" TEXT NOT NULL, "owner_account_id" TEXT NOT NULL, "contest_id" TEXT NULL, "stamped_entity_type" TEXT NOT NULL, "stamped_entity_id" TEXT NOT NULL, "source_system" TEXT NOT NULL, "source_keys" TEXT NOT NULL, "source_values" TEXT NULL, "file_fingerprint" TEXT NOT NULL, "dedupe_key" TEXT NULL, "import_operation_id" TEXT NOT NULL, "tool_version" TEXT NOT NULL, "imported_at" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("owner_account_id", "dedupe_key"));
CREATE TABLE IF NOT EXISTS "pilot_import_links" ("id" TEXT NOT NULL, "owner_account_id" TEXT NOT NULL, "source_system" TEXT NOT NULL, "source_pilot_no" INTEGER NOT NULL, "participant_profile_id" TEXT NOT NULL, "source_values" TEXT NOT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("owner_account_id", "source_system", "source_pilot_no"));
CREATE TABLE IF NOT EXISTS "accounts" ("id" TEXT NOT NULL, "first_name" TEXT NOT NULL, "last_name" TEXT NOT NULL, "email" TEXT NULL, "email_verified" INTEGER NOT NULL CHECK ("email_verified" IN (0, 1)), "kind" TEXT NOT NULL CHECK("kind" IN ('registered', 'guest', 'local', 'deleted')), "status" TEXT NOT NULL CHECK("status" IN ('active', 'archived')), "archived_at" TEXT NULL, "is_system_admin" INTEGER NOT NULL CHECK ("is_system_admin" IN (0, 1)), "preferred_time_zone" TEXT NULL, "preferred_locale" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("email"), CHECK (email IS NULL OR email = lower(email)));
CREATE TABLE IF NOT EXISTS "account_aliases" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id), "claimed_at" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "account_identities" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id), "issuer" TEXT NOT NULL, "subject" TEXT NOT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("issuer", "subject"));
CREATE TABLE IF NOT EXISTS "account_public_profiles" ("id" TEXT NOT NULL, "account_id" TEXT NULL REFERENCES accounts (id), "display_name" TEXT NOT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("account_id"));
CREATE TABLE IF NOT EXISTS "participant_account_links" ("id" TEXT NOT NULL, "participant_profile_id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id), "status" TEXT NOT NULL CHECK("status" IN ('Candidate', 'Confirmed', 'Ended')), "origin" TEXT NOT NULL CHECK("origin" IN ('EmailMatch', 'DirectoryPull', 'InvitationRedemption')), "created_at" TEXT NOT NULL, "confirmed_at" TEXT NULL, "ended_at" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("participant_profile_id", "account_id"));
CREATE TABLE IF NOT EXISTS "participant_directory_entries" ("id" TEXT NOT NULL, "account_id" TEXT NOT NULL REFERENCES accounts (id), "first_name" TEXT NOT NULL, "last_name" TEXT NOT NULL, "club" TEXT NULL, "fai_number" TEXT NULL, "national_org_id" TEXT NULL, "city" TEXT NULL, "state" TEXT NULL, "country" TEXT NULL, "is_listed" INTEGER NOT NULL CHECK ("is_listed" IN (0, 1)), "email_visible_to_directors" INTEGER NOT NULL CHECK ("email_visible_to_directors" IN (0, 1)), "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("account_id"));
CREATE TABLE IF NOT EXISTS "installations" ("id" TEXT NOT NULL, "owner_account_id" TEXT NOT NULL REFERENCES accounts (id), "label" TEXT NOT NULL, "platform" TEXT NOT NULL CHECK("platform" IN ('Web', 'Windows', 'Other')), "created_at" TEXT NOT NULL, "last_seen_at" TEXT NULL, "last_sync_at" TEXT NULL, "system_data_seq" INTEGER NOT NULL, "revoked_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "installation_activations" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL, "installation_id" TEXT NOT NULL REFERENCES installations (id), "activated_by" TEXT NOT NULL REFERENCES accounts (id), "kind" TEXT NOT NULL CHECK("kind" IN ('Initial', 'Replacement', 'Reclaim')), "activated_at" TEXT NOT NULL, "ended_at" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "sync_cursors" ("id" TEXT NOT NULL, "installation_id" TEXT NOT NULL REFERENCES installations (id), "contest_id" TEXT NULL, "owner_account_id" TEXT NULL REFERENCES accounts (id), "last_synced_sequence" INTEGER NOT NULL, "last_synced_at" TEXT NULL, "updated_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("installation_id", "contest_id"), UNIQUE ("installation_id", "owner_account_id"), CHECK ((contest_id IS NULL) <> (owner_account_id IS NULL)));
CREATE TABLE IF NOT EXISTS "publication_identities" ("id" TEXT NOT NULL, "contest_id" TEXT NULL REFERENCES contests (id) ON DELETE SET NULL, "owner_public_profile_id" TEXT NULL REFERENCES account_public_profiles (id), "claim_status" TEXT NOT NULL CHECK("claim_status" IN ('Unclaimed', 'Claimed')), "verification_email" TEXT NULL, "visibility" TEXT NOT NULL CHECK("visibility" IN ('Unlisted', 'Public', 'Delisted')), "published_at" TEXT NULL, "current_projection_id" TEXT NULL, "results_hidden_through_round" INTEGER NULL, "results_hidden_at" TEXT NULL, "contest_name" TEXT NULL, "contest_starts_at" TEXT NULL, "contest_ends_at" TEXT NULL, "venue" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), CHECK ((results_hidden_at IS NULL) = (results_hidden_through_round IS NULL)));
CREATE TABLE IF NOT EXISTS "publication_projections" ("id" TEXT NOT NULL, "publication_id" TEXT NOT NULL REFERENCES publication_identities (id), "projection_revision" INTEGER NOT NULL, "contest_revision" INTEGER NOT NULL, "config_revision" INTEGER NOT NULL, "matrix_revision" INTEGER NOT NULL, "discipline_type" TEXT NOT NULL CHECK("discipline_type" IN ('ALES', 'ThermalDuration', 'F3J', 'F5J', 'F3L', 'F3K')), "discipline_rules_version" INTEGER NOT NULL, "calculation_version" TEXT NOT NULL, "contest_identity" TEXT NOT NULL, "participants" TEXT NULL, "teams" TEXT NULL, "matrix_info" TEXT NULL, "scores" TEXT NULL, "standings" TEXT NULL, "calculation_metadata" TEXT NULL, "published_at" TEXT NOT NULL, "published_by" TEXT NULL REFERENCES accounts (id), "client_mutation_id" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("publication_id", "projection_revision"), UNIQUE ("publication_id", "client_mutation_id"));
CREATE TABLE IF NOT EXISTS "publication_participants" ("id" TEXT NOT NULL, "publication_id" TEXT NOT NULL REFERENCES publication_identities (id), "pilot_key" TEXT NOT NULL, "source_participation_id" TEXT NULL, "details" TEXT NULL, "public_profile_id" TEXT NULL REFERENCES account_public_profiles (id), "redacted_at" TEXT NULL, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("publication_id", "pilot_key"), CHECK (redacted_at IS NULL OR (details IS NULL AND public_profile_id IS NULL)));
CREATE TABLE IF NOT EXISTS "delist_requests" ("id" TEXT NOT NULL, "publication_id" TEXT NOT NULL REFERENCES publication_identities (id), "requested_by" TEXT NOT NULL REFERENCES accounts (id), "trigger" TEXT NOT NULL CHECK("trigger" IN ('owner_request', 'account_closure')), "reason" TEXT NULL, "requested_at" TEXT NOT NULL, "state" TEXT NOT NULL CHECK("state" IN ('pending', 'approved', 'denied', 'withdrawn')), "decided_by" TEXT NULL REFERENCES accounts (id), "decided_at" TEXT NULL, "decision_note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "request_throttles" ("bucket" TEXT NOT NULL, "caller" TEXT NOT NULL, "window_start" TEXT NOT NULL, "count" INTEGER NOT NULL, PRIMARY KEY ("bucket", "caller"));
CREATE TABLE IF NOT EXISTS "invitations" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "type" TEXT NOT NULL CHECK("type" IN ('MagicURL', 'QRCode')), "protected_credential" TEXT NOT NULL, "invitation_revision" INTEGER NOT NULL, "state" TEXT NOT NULL CHECK("state" IN ('Active', 'Replaced', 'Revoked', 'Expired')), "audience" TEXT NOT NULL CHECK("audience" IN ('Pilot', 'Helper')), "issued_by" TEXT NOT NULL, "issued_at" TEXT NOT NULL, "expires_at" TEXT NULL, "first_used_at" TEXT NULL, "last_used_at" TEXT NULL, "revoked_at" TEXT NULL, "replaces_invitation_id" TEXT NULL REFERENCES invitations (id), "redeemed_by_account_id" TEXT NULL, "delivery_outcomes" TEXT NOT NULL, "client_mutation_id" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("contest_participation_id", "invitation_revision"), UNIQUE ("contest_id", "client_mutation_id"), CHECK (state <> 'Revoked' OR revoked_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS "matrix_revisions" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "revision_number" INTEGER NOT NULL, "previous_revision_id" TEXT NULL REFERENCES matrix_revisions (id), "first_round" INTEGER NOT NULL, "last_round" INTEGER NOT NULL, "draw_mode" TEXT NOT NULL CHECK("draw_mode" IN ('StandardManOnMan', 'SeededManOnMan')), "random_seed" INTEGER NOT NULL, "algorithm_version" TEXT NOT NULL, "draw_config" TEXT NOT NULL, "seeding_snapshot" TEXT NOT NULL, "fairness_summary" TEXT NULL, "reason" TEXT NULL, "created_by" TEXT NOT NULL, "created_at" TEXT NOT NULL, "finalized_by" TEXT NULL, "finalized_at" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("contest_id", "revision_number"), CHECK (first_round >= 1 AND first_round <= last_round));
CREATE TABLE IF NOT EXISTS "rounds" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "matrix_revision_id" TEXT NOT NULL REFERENCES matrix_revisions (id), "ordinal" INTEGER NOT NULL, "group_count" INTEGER NOT NULL, "status" TEXT NOT NULL CHECK("status" IN ('Open', 'Locked', 'Cancelled')), "superseded_by_round_id" TEXT NULL REFERENCES rounds (id) DEFERRABLE INITIALLY DEFERRED, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("matrix_revision_id", "ordinal"), CHECK (ordinal >= 1 AND group_count >= 1));
CREATE TABLE IF NOT EXISTS "round_groups" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "round_id" TEXT NOT NULL REFERENCES rounds (id), "group_number" INTEGER NOT NULL, "status" TEXT NOT NULL CHECK("status" IN ('Open', 'Locked')), "locked_by" TEXT NULL, "locked_at" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("round_id", "group_number"), CHECK (group_number >= 1), CHECK ((status = 'Locked') = (locked_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS "re_flights" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "credited_round_id" TEXT NOT NULL REFERENCES rounds (id), "source_round_id" TEXT NOT NULL REFERENCES rounds (id), "source_group" INTEGER NOT NULL, "type" TEXT NOT NULL CHECK("type" IN ('MoveToGroup', 'RandomDraw', 'ReflyEntireGroup')), "sequence" INTEGER NOT NULL, "previous_reflight_id" TEXT NULL REFERENCES re_flights (id), "status" TEXT NOT NULL CHECK("status" IN ('Proposed', 'DrawPending', 'AwaitingResponses', 'ReadyToFly', 'Finalized', 'Cancelled')), "reason" TEXT NOT NULL, "scheduled_round_id" TEXT NOT NULL REFERENCES rounds (id), "flown_group" INTEGER NOT NULL, "deviation_acknowledged" INTEGER NOT NULL CHECK ("deviation_acknowledged" IN (0, 1)), "requested_group_size" INTEGER NULL, "achievable_max_size" INTEGER NULL, "size_exception_confirmed" INTEGER NOT NULL CHECK ("size_exception_confirmed" IN (0, 1)), "random_seed" INTEGER NULL, "algorithm_version" TEXT NULL, "config_revision_id" TEXT NOT NULL REFERENCES contest_configuration_revisions (id), "created_by" TEXT NOT NULL, "created_at" TEXT NOT NULL, "group_finalized_by" TEXT NULL, "group_finalized_at" TEXT NULL, "finalized_by" TEXT NULL, "finalized_at" TEXT NULL, "cancelled_by" TEXT NULL, "cancelled_at" TEXT NULL, "cancel_reason" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("source_round_id", "source_group", "sequence"));
CREATE TABLE IF NOT EXISTS "matrix_assignments" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "matrix_revision_id" TEXT NOT NULL REFERENCES matrix_revisions (id), "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "scheduled_round_id" TEXT NOT NULL REFERENCES rounds (id), "credited_round_id" TEXT NOT NULL REFERENCES rounds (id), "group" INTEGER NOT NULL, "lane" INTEGER NULL, "flight_sequence" INTEGER NOT NULL, "assignment_type" TEXT NOT NULL CHECK("assignment_type" IN ('Original', 'Moved', 'Reflight', 'LateAdd')), "source_assignment_id" TEXT NULL REFERENCES matrix_assignments (id), "re_flight_id" TEXT NULL REFERENCES re_flights (id), "superseded_by_assignment_id" TEXT NULL REFERENCES matrix_assignments (id) DEFERRABLE INITIALLY DEFERRED, "actor_id" TEXT NOT NULL, "reason" TEXT NULL, "existing_score_handling" TEXT NOT NULL CHECK("existing_score_handling" IN ('None', 'Reset')), "reset_score_revision" INTEGER NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("id"), CHECK ("group" >= 1 AND flight_sequence >= 1), CHECK ((assignment_type IN ('Moved', 'Reflight')) = (source_assignment_id IS NOT NULL)), CHECK ((assignment_type = 'Reflight') = (re_flight_id IS NOT NULL)), CHECK (assignment_type = 'Original' OR reason IS NOT NULL), CHECK (reset_score_revision IS NULL OR existing_score_handling = 'Reset'));
CREATE TABLE IF NOT EXISTS "re_flight_participants" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "re_flight_id" TEXT NOT NULL REFERENCES re_flights (id), "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "role" TEXT NOT NULL CHECK("role" IN ('Awarded', 'Drawn', 'GroupMember', 'Candidate', 'Excluded')), "excluded_reason" TEXT NULL CHECK("excluded_reason" IN ('SameTeam', 'Retired', 'NotEligible', 'DirectorExcluded', 'Declined')), "draw_position" INTEGER NULL, "response" TEXT NOT NULL CHECK("response" IN ('NotRequired', 'Pending', 'Accepted', 'Declined')), "responded_by" TEXT NULL CHECK("responded_by" IN ('Participant', 'Director')), "responded_at" TEXT NULL, "notification_state" TEXT NOT NULL CHECK("notification_state" IN ('NotRequired', 'Pending', 'Delivered', 'Failed')), "notified_at" TEXT NULL, "acknowledged_at" TEXT NULL, "assignment_id" TEXT NULL REFERENCES matrix_assignments (id), "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("re_flight_id", "contest_participation_id"), CHECK ((role = 'Excluded') = (excluded_reason IS NOT NULL)));
CREATE TABLE IF NOT EXISTS "score_placeholders" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "assignment_id" TEXT NOT NULL REFERENCES matrix_assignments (id), "state" TEXT NOT NULL CHECK("state" IN ('NotEntered', 'Submitted', 'InReview', 'Official')), "score_revision" INTEGER NOT NULL, "current_attempt_id" TEXT NULL, "locked_by" TEXT NULL, "locked_at" TEXT NULL, "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), UNIQUE ("assignment_id"), CHECK (score_revision >= 0), CHECK ((locked_by IS NULL) = (locked_at IS NULL)));
CREATE TABLE IF NOT EXISTS "score_attempts" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "score_placeholder_id" TEXT NOT NULL REFERENCES score_placeholders (id), "config_revision_id" TEXT NOT NULL REFERENCES contest_configuration_revisions (id), "matrix_revision_id" TEXT NOT NULL REFERENCES matrix_revisions (id), "raw_components" TEXT NOT NULL, "actor_id" TEXT NOT NULL, "authority" TEXT NOT NULL CHECK("authority" IN ('Director', 'Participant', 'Helper', 'System', 'Administrator')), "invitation_id" TEXT NULL, "source_device" TEXT NULL, "client_mutation_id" TEXT NOT NULL, "base_score_revision" INTEGER NOT NULL, "accepted_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("contest_id", "client_mutation_id"));
CREATE TABLE IF NOT EXISTS "official_scores" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "score_placeholder_id" TEXT NOT NULL REFERENCES score_placeholders (id), "score_attempt_id" TEXT NOT NULL REFERENCES score_attempts (id), "score_revision" INTEGER NOT NULL, "components" TEXT NOT NULL, "set_at" TEXT NOT NULL, "set_by" TEXT NOT NULL, "reason" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("score_placeholder_id", "score_revision"), CHECK (score_revision >= 1));
CREATE TABLE IF NOT EXISTS "review_requests" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "score_placeholder_id" TEXT NOT NULL REFERENCES score_placeholders (id), "proposed_components" TEXT NOT NULL, "participant_message" TEXT NULL, "requester_id" TEXT NOT NULL, "base_score_revision" INTEGER NOT NULL, "requested_at" TEXT NOT NULL, "state" TEXT NOT NULL CHECK("state" IN ('Submitted', 'UnderReview', 'Approved', 'Rejected', 'Superseded')), "decision_actor_id" TEXT NULL, "decision_time" TEXT NULL, "decision_message" TEXT NULL, "resulting_attempt_id" TEXT NULL REFERENCES score_attempts (id), "revision" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"), CHECK (state <> 'Submitted' OR (decision_actor_id IS NULL AND decision_time IS NULL AND resulting_attempt_id IS NULL)));
CREATE TABLE IF NOT EXISTS "flight_results" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "score_placeholder_id" TEXT NOT NULL REFERENCES score_placeholders (id), "official_score_id" TEXT NOT NULL REFERENCES official_scores (id), "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "credited_round_id" TEXT NOT NULL REFERENCES rounds (id), "outcome" TEXT NOT NULL CHECK("outcome" IN ('Scored', 'Zero')), "raw_points" REAL NOT NULL, "landing_points" REAL NULL, "flight_penalty_points" REAL NULL, "cumulative_penalty" INTEGER NULL, "group_score" REAL NOT NULL, "is_selected" INTEGER NOT NULL CHECK ("is_selected" IN (0, 1)), "is_preliminary" INTEGER NOT NULL CHECK ("is_preliminary" IN (0, 1)), "config_revision_id" TEXT NOT NULL REFERENCES contest_configuration_revisions (id), "matrix_revision_id" TEXT NOT NULL REFERENCES matrix_revisions (id), "calculation_version" TEXT NOT NULL, "computed_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("score_placeholder_id"), CHECK (raw_points >= 0));
CREATE TABLE IF NOT EXISTS "participation_standings" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "contest_participation_id" TEXT NOT NULL REFERENCES contest_participations (id), "as_of_round" INTEGER NOT NULL, "place" INTEGER NOT NULL, "is_tied" INTEGER NOT NULL CHECK ("is_tied" IN (0, 1)), "raw_total" REAL NOT NULL, "dropped_rounds" TEXT NOT NULL, "penalty_total" REAL NOT NULL, "overall_score" REAL NOT NULL, "is_preliminary" INTEGER NOT NULL CHECK ("is_preliminary" IN (0, 1)), "config_revision_id" TEXT NOT NULL REFERENCES contest_configuration_revisions (id), "matrix_revision_id" TEXT NOT NULL REFERENCES matrix_revisions (id), "calculation_version" TEXT NOT NULL, "computed_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("contest_participation_id", "as_of_round"));
CREATE TABLE IF NOT EXISTS "team_standings" ("id" TEXT NOT NULL, "contest_id" TEXT NOT NULL REFERENCES contests (id) ON DELETE CASCADE, "team_id" TEXT NOT NULL REFERENCES teams (id), "as_of_round" INTEGER NOT NULL, "place" INTEGER NOT NULL, "is_tied" INTEGER NOT NULL CHECK ("is_tied" IN (0, 1)), "team_score" REAL NOT NULL, "counted_participations" TEXT NOT NULL, "is_preliminary" INTEGER NOT NULL CHECK ("is_preliminary" IN (0, 1)), "config_revision_id" TEXT NOT NULL REFERENCES contest_configuration_revisions (id), "matrix_revision_id" TEXT NOT NULL REFERENCES matrix_revisions (id), "calculation_version" TEXT NOT NULL, "computed_at" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("team_id", "as_of_round"));
CREATE TABLE IF NOT EXISTS "mutation_records" ("id" TEXT NOT NULL, "contest_id" TEXT NULL, "owner_account_id" TEXT NULL, "sequence" INTEGER NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "base_revision" INTEGER NULL, "client_mutation_id" TEXT NOT NULL, "actor_id" TEXT NULL, "authority" TEXT NOT NULL CHECK("authority" IN ('Director', 'Participant', 'Helper', 'System', 'Administrator')), "source_installation_id" TEXT NULL, "source_device" TEXT NULL, "client_time" TEXT NOT NULL, "server_acceptance_time" TEXT NULL, "server_rejection_time" TEXT NULL, "payload" TEXT NOT NULL, "outcome" TEXT NOT NULL CHECK("outcome" IN ('Pending', 'Accepted', 'Rejected', 'Conflict', 'Skipped')), "reason_code" TEXT NULL, "error_message" TEXT NULL, "depends_on_mutation_id" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("contest_id", "client_mutation_id"), UNIQUE ("owner_account_id", "client_mutation_id"), UNIQUE ("contest_id", "sequence"), UNIQUE ("owner_account_id", "sequence"), CHECK ((contest_id IS NULL) <> (owner_account_id IS NULL)), CHECK (sequence IS NULL OR outcome = 'Accepted'));
CREATE TABLE IF NOT EXISTS "conflict_records" ("id" TEXT NOT NULL, "contest_id" TEXT NULL, "owner_account_id" TEXT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "accepted_mutation_id" TEXT NULL, "competing_mutation_id" TEXT NOT NULL, "reason_code" TEXT NOT NULL, "reason" TEXT NULL, "requires_action" INTEGER NOT NULL DEFAULT 1 CHECK ("requires_action" IN (0, 1)), "resolution" TEXT NOT NULL CHECK("resolution" IN ('Pending', 'Automatic', 'Manual')), "resolution_choice" TEXT NULL CHECK("resolution_choice" IN ('KeptAccepted', 'TookCompeting', 'Merged')), "created_at" TEXT NOT NULL, "resolved_at" TEXT NULL, "resolved_by" TEXT NULL, "accepted_payload" TEXT NULL, "competing_payload" TEXT NULL, "entity_revision" INTEGER NULL, PRIMARY KEY ("id"), CHECK ((contest_id IS NULL) <> (owner_account_id IS NULL)));
CREATE TABLE IF NOT EXISTS "tombstones" ("id" TEXT NOT NULL, "contest_id" TEXT NULL, "owner_account_id" TEXT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "status" TEXT NOT NULL CHECK("status" IN ('Pending', 'Acknowledged')), "deleted_at" TEXT NOT NULL, "acknowledged_at" TEXT NULL, "purge_after" TEXT NULL, "deletion_reason" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("entity_type", "entity_id"), CHECK ((contest_id IS NULL) <> (owner_account_id IS NULL)));
CREATE TABLE IF NOT EXISTS "audit_events" ("id" TEXT NOT NULL, "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "contest_id" TEXT NULL, "owner_account_id" TEXT NULL, "publication_id" TEXT NULL, "action" TEXT NOT NULL CHECK("action" IN ('StateTransition', 'ScoreAttempt', 'ScoreReview', 'InvitationIssued', 'InvitationReplaced', 'InvitationRevoked', 'InvitationDeliveryRequested', 'InvitationAccessed', 'InvitationAccessFailed', 'PublicationAttempt', 'DelistRequested', 'DelistDecided', 'DelistWithdrawn', 'Redaction', 'Conflict', 'ConflictAccepted', 'ConflictRejected', 'Deletion', 'Restoration', 'InstallationActivation', 'ConfigurationSaved', 'MatrixDrawn')), "actor_id" TEXT NULL, "authority" TEXT NOT NULL CHECK("authority" IN ('Director', 'Participant', 'Helper', 'System', 'Administrator')), "installation_id" TEXT NULL, "device" TEXT NULL, "base_revision" INTEGER NULL, "resulting_revision" INTEGER NULL, "server_timestamp" TEXT NOT NULL, "client_timestamp" TEXT NULL, "reason" TEXT NULL, "outcome" TEXT NOT NULL CHECK("outcome" IN ('Success', 'Rejected', 'Conflict')), PRIMARY KEY ("id"), CHECK ((CASE WHEN contest_id IS NULL THEN 0 ELSE 1 END) + (CASE WHEN owner_account_id IS NULL THEN 0 ELSE 1 END) + (CASE WHEN publication_id IS NULL THEN 0 ELSE 1 END) <= 1));
CREATE TABLE IF NOT EXISTS "local_sync_positions" ("scope_kind" TEXT NOT NULL CHECK("scope_kind" IN ('Contest', 'Director', 'System')), "scope_id" TEXT NOT NULL, "last_synced_sequence" INTEGER NOT NULL DEFAULT 0, "last_synced_at" TEXT NULL, PRIMARY KEY ("scope_kind", "scope_id"));
CREATE TABLE IF NOT EXISTS "local_account" ("slot" INTEGER NOT NULL CHECK("slot" = 1), "account_id" TEXT NOT NULL, "preferred_time_zone" TEXT NULL, "preferred_locale" TEXT NULL, "linked_account_id" TEXT NULL, "linked_subject" TEXT NULL, "created_at" TEXT NOT NULL, PRIMARY KEY ("slot"));
CREATE INDEX publication_identities_listing ON publication_identities (visibility, contest_starts_at DESC);
CREATE UNIQUE INDEX accounts_one_deleted ON accounts (kind) WHERE kind = 'deleted';
CREATE UNIQUE INDEX participant_account_links_one_confirmed ON participant_account_links (participant_profile_id) WHERE status = 'Confirmed';
CREATE UNIQUE INDEX installation_activations_one_open ON installation_activations (contest_id) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX delist_requests_one_pending ON delist_requests (publication_id) WHERE state = 'pending';
CREATE UNIQUE INDEX invitations_one_active ON invitations (contest_participation_id) WHERE state = 'Active';
CREATE UNIQUE INDEX matrix_revisions_one_finalized_successor ON matrix_revisions (contest_id, COALESCE(previous_revision_id, '')) WHERE finalized_at IS NOT NULL;
CREATE UNIQUE INDEX rounds_live_ordinal ON rounds (contest_id, ordinal) WHERE superseded_by_round_id IS NULL AND status <> 'Cancelled';
CREATE INDEX IF NOT EXISTS rounds_contest ON rounds (contest_id);
CREATE UNIQUE INDEX matrix_assignments_live_lane ON matrix_assignments (scheduled_round_id, "group", lane) WHERE lane IS NOT NULL AND superseded_by_assignment_id IS NULL;
CREATE UNIQUE INDEX matrix_assignments_live_participation ON matrix_assignments (contest_participation_id, credited_round_id) WHERE superseded_by_assignment_id IS NULL AND assignment_type IN ('Original', 'Moved', 'LateAdd');
CREATE INDEX IF NOT EXISTS matrix_assignments_scheduled_round ON matrix_assignments (scheduled_round_id);
CREATE INDEX IF NOT EXISTS score_placeholders_contest ON score_placeholders (contest_id);
CREATE INDEX IF NOT EXISTS score_placeholders_participation ON score_placeholders (contest_participation_id);
CREATE INDEX IF NOT EXISTS score_attempts_placeholder ON score_attempts (score_placeholder_id);
CREATE INDEX IF NOT EXISTS flight_results_contest_round ON flight_results (contest_id, credited_round_id);
CREATE INDEX IF NOT EXISTS participation_standings_contest_round ON participation_standings (contest_id, as_of_round);
CREATE UNIQUE INDEX review_requests_one_open ON review_requests (score_placeholder_id) WHERE state IN ('Submitted', 'UnderReview');
CREATE UNIQUE INDEX roles_owner_display_name ON roles (COALESCE(owner_account_id, ''), lower(display_name));
CREATE UNIQUE INDEX roles_one_pilot ON roles (type) WHERE type = 'Pilot';
CREATE UNIQUE INDEX contest_configuration_presets_owner_name ON contest_configuration_presets (owner_account_id, lower(name));
CREATE UNIQUE INDEX model_catalogs_profile_name_manufacturer ON model_catalogs (participant_profile_id, lower(name), lower(COALESCE(manufacturer, '')));
CREATE UNIQUE INDEX import_provenance_one_per_entity ON import_provenance (stamped_entity_type, stamped_entity_id) WHERE stamped_entity_type <> 'ParticipantProfile';
CREATE UNIQUE INDEX import_provenance_one_per_operation ON import_provenance (stamped_entity_id, import_operation_id);
CREATE UNIQUE INDEX discipline_formulas_one_primary ON discipline_formulas (discipline_profile_id) WHERE is_primary;
